{"source":"#include<stdio.h>
#define N 1000
#include<stdlib.h>
#include<math.h>
#define MAX_N 10000
int heap[MAX_N],size=0;
void print(){
	int i;
	for(i=0;i<size;i++){
		printf(" %d",heap[i]);
	}
	printf("\n");
}

void push(int x) {
	int i=size;
	size++;
	while(i>0) {
		int p=(i-1)/2;
		if(heap[p]>=x) break;
		heap[i]=heap[p];
		i=p;
	}
	heap[i]=x;
}
int pop() {
	int ret=heap[0];
	size--;
	int x=heap[size];

	int i=0;
	while(i*2+1<size) {
		int a=i*2+1,b=i*2+2;
		int max=a;
		if(b<size && heap[b]>heap[a]) max=b;
		if(heap[max]<=x) break;
		heap[i]=heap[max];
		i=max;
	}
	heap[i]=x;
	return ret;
}
void sort(int a[],int n){
	int i,j;
	for(i=0;i<n-1;i++){
		int min=i;
		for(j=i+1;j<n;j++){
			if(a[j]<a[min]){
				min=j;
			}
		}
		if(min!=i){
			int tmp=a[min];
			a[min]=a[i];
			a[i]=tmp;
		}
	}
}
int main(int argc, char *argv[]) {
	int n,m;
	scanf("%d%d",&n,&m);
	int i;
	int seat[N];
	for(i=0;i<m;i++){
		scanf("%d",&seat[i]);
		push(seat[i]);
	}
	sort(seat,m);
	int min=0;
	int people=n;
	for(i=0;i<m;i++){
		if(people==0)break;
		if(seat[i]>=people){
			int big=seat[i];
			int small=seat[i]-people+1;
			min+=((big+small)*people)/2;
			people=0;
		}else{
			min+=seat[i]*(seat[i]+1)/2;
			people=people-seat[i];
		}
	}
	int max=0;
	for(i=0;i<n;i++){
		int get=pop();
		max+=get;
		if(get-1>0)push(get-1);
	}
	printf("%d %d\n",max,min);

	return 0;
}"}
